public class TrailEncoderTest
{
	public static final String ENCODED_TRAIL =
		"eJxNUUtuFDEQLSCQoZVIbFhTB0giJQEkEJth6CSI-UDPwLCtjmvaVrvtlu2" +
			"kk12WLLgAJ-EUcwk2XIPqXkQsnlSu8qvPe6tiegwAOTwN5JRv0CjIVh" +
			"wTpkDGwqjR3lrjanj8AN6s6ZrROEyaUXkf0LfsjKvQb4bc9Kopg1EV4" +
			"4Risoy1SZea3ZGMGAHs_RD8lBgewosvRb7EfF6Msfg0x2I2fp8vsPh6" +
			"jpOL75-_TQCeb2Fn6qsIoxXVfEg3LOwg2PYdHsGrl6i4CswRT15jY9x" +
			"VktD5kHR2cnxfOz29r7EsJfy3gr99jyewP_6Iy8X0A64Xs3wuS76Dvb" +
			"WJjAurcEYOdldk68PkhfJM8Lun7cB2rTmIBBRqxzGiCqaNWLJjSnpQo" +
			"vTVn7tfEaP1HZahzx9kS-Yaram0qKsp4YYpxOH7pQgb3MC4pW6QVHGb" +
			"9FE2brw8-j9yjYrYDZOtF4c2lhq5quu5KO5hlNYH2ZmRsCfUzK1UxJu" +
			"OQiOLlbzxQo6alO8itiSrl7dizq6G_Yl0EMciW8vh_7tLge7v_geXrqYX";

	public static final TreasureTrail TRAIL = new TreasureTrail(
		69,
		"random id",
		"Test trail",
		"mhollink",
		List.of(
			new EmoteStep("Wave in the door opening of the Lumbridge Castle kitchen.",
				Emote.WAVE,
				new WorldPoint(3208, 3212, 0)),
			new InteractionStep(StepType.CIPHER_STEP, "QRES ENRA RKN RMABEO RUG CHXPVC",
				new InteractionStep.Target(
					5581,
					"Logs",
					"Take-axe",
					new WorldPoint(3186, 3277, 0)
				)),
			new CoordsStep(
				"4 degrees 26 minutes north\n21 degrees 33 minutes east",
				new WorldPoint(3130, 3303, 0)),
			new InteractionStep(StepType.ANAGRAM_STEP,
				"AI SOLD WOMEN",
				new InteractionStep.Target(
					2108,
					"Wise Old Man",
					"Talk-to",
					new WorldPoint(3088, 3255, 0)
				)),
			new InteractionStep(StepType.CRYPTIC_STEP,
				"Where darkness drips beneath the bog’s slow breath,\n" +
					"Seek light that fears the cavern’s yawning depth.\n" +
					"Among the reeds where lost flames waver and sigh,\n" +
					"Find the keeper of warmth before shadows pass by.",
				new InteractionStep.Target(
					1896,
					"Candle seller",
					"Talk-to",
					new WorldPoint(3170, 3176, 0)
				))
		)
	);

	@Test
	public void encode() throws Exception
	{
		TrailCodec codec = new TrailCodec();

		String encodedTrail = codec.encodeToString(TRAIL);

		assertThat(encodedTrail, equalTo(ENCODED_TRAIL));
	}

	@Test
	public void decode() throws Exception
	{
		TrailCodec codec = new TrailCodec();

		TreasureTrail decodedTrail = codec.decode(ENCODED_TRAIL);

		assertThat(decodedTrail.getMetadata().getVersion(), equalTo(TRAIL.getMetadata().getVersion()));
		assertThat(decodedTrail.getMetadata().getTrailId(), equalTo(TRAIL.getMetadata().getTrailId()));
		assertThat(decodedTrail.getMetadata().getTrailName(), equalTo(TRAIL.getMetadata().getTrailName()));
		assertThat(decodedTrail.getMetadata().getAuthor(), equalTo(TRAIL.getMetadata().getAuthor()));

		for (int i = 0; i < TRAIL.getMetadata().getStepCount(); i++)
		{
			TrailStep trailStep = TRAIL.getStep(i).orElseThrow();
			TrailStep decodedStep = decodedTrail.getStep(i).orElseThrow();

			assertThat(decodedStep, equalTo(trailStep));
		}
	}
}

package dev.hollink.partytrails;

import com.google.inject.Provides;
import dev.hollink.partytrails.engine.PartyTrailManager;
import dev.hollink.partytrails.events.TrailEventBus;
import dev.hollink.partytrails.events.events.ClueEventFactory;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Party Trails",
	description = "Create and complete custom player made treasure trails",
	tags = {"clue", "treasure", "party"})
public class PartyTrailsPlugin extends Plugin
{

	@Inject
	private Client client;

	@Inject
	private PartyTrailManager party;

	@Inject
	private TrailEventBus clueEventBus;

	@Override
	protected void startUp() throws Exception
	{
		party.start();
	}

	@Override
	protected void shutDown() throws Exception
	{
		party.stop();
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		ClueEventFactory.fromAnimationChanged(event, client).ifPresent(clueEvent -> {
			log.debug("Publishing Animation Event {}", clueEvent);
			clueEventBus.publish(clueEvent);
		});
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		ClueEventFactory.fromMenuOptionClicked(event, client).ifPresent(clueEvent -> {
			log.debug("Publishing Interaction Event {}", clueEvent);
			clueEventBus.publish(clueEvent);
		});
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		ClueEventFactory.fromStatChanged(event, client).ifPresent(clueEvent -> {
			log.debug("Publishing Skill Event {}", clueEvent);
			clueEventBus.publish(clueEvent);
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals(PartyTrailsConfig.CONFIG_GROUP))
		{
			return;
		}

		if (event.getKey().equals(PartyTrailsConfig.TREASURE_TRAIL))
		{
			party.resumeOrStartTrailFromConfig();
		}

		if (event.getKey().equals(PartyTrailsConfig.SHOW_BUILDER_PANEL))
		{
			party.updateBuilderPanelVisibility();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		party.onGamestateChanged(gameStateChanged.getGameState());
	}

	@Provides
	PartyTrailsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PartyTrailsConfig.class);
	}
}

