package dev.hollink.partytrails.codec;

public interface Codec<T> extends Encoder<T>, Decoder<T>
{
}

package dev.hollink.partytrails.codec;

import java.io.ByteArrayOutputStream;
import java.io.DataOutput;
import java.io.DataOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.zip.DeflaterOutputStream;

public interface Encoder<T>
{
	default void writeString(DataOutput out, String value) throws IOException
	{
		byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
		out.writeShort(bytes.length);
		out.write(bytes);
	}

	void encode(T value, DataOutput out) throws IOException;

	default String encodeToString(T value) throws IOException
	{
		ByteArrayOutputStream bos = new ByteArrayOutputStream();
		DeflaterOutputStream dos = new DeflaterOutputStream(bos);
		DataOutputStream out = new DataOutputStream(dos);

		encode(value, out);

		out.flush();
		dos.finish();

		return Base64.getUrlEncoder()
			.withoutPadding()
			.encodeToString(bos.toByteArray());
	}
}

package dev.hollink.partytrails.codec;

import java.io.ByteArrayInputStream;
import java.io.DataInput;
import java.io.DataInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.zip.InflaterInputStream;

public interface Decoder<T>
{

	default String readString(DataInput in) throws IOException
	{
		int length = in.readUnsignedShort();
		byte[] bytes = new byte[length];
		in.readFully(bytes);
		return new String(bytes, StandardCharsets.UTF_8);
	}

	T decode(DataInput in) throws IOException;

	default T decode(String value) throws IOException
	{
		byte[] data = Base64.getUrlDecoder().decode(value);
		ByteArrayInputStream bis = new ByteArrayInputStream(data);
		InflaterInputStream ii = new InflaterInputStream(bis);
		DataInput in = new DataInputStream(ii);

		return decode(in);
	}
}

package dev.hollink.partytrails.engine.hunter;

import dev.hollink.partytrails.data.TreasureTrail;
import dev.hollink.partytrails.data.steps.TrailStep;
import dev.hollink.partytrails.data.trail.TrailContext;
import dev.hollink.partytrails.events.Subscription;
import dev.hollink.partytrails.events.TrailEventBus;
import dev.hollink.partytrails.events.events.TrailCompletedEvent;
import dev.hollink.partytrails.events.events.TrailStepCompletedEvent;
import dev.hollink.partytrails.engine.hunter.handlers.StepHandler;
import dev.hollink.partytrails.engine.hunter.handlers.StepHandlerFactory;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class TrailHunterEngine
{
	private final TrailEventBus events;
	private final StepHandlerFactory stepHandlerFactory;

	private TreasureTrail trail;
	private TrailContext context;
	private Subscription subscription;

	private int currentIndex;
	private StepHandler<?> activeHandler;

	public void start(TreasureTrail trail, TrailContext context)
	{
		this.trail = trail;
		this.context = context;
		this.currentIndex = 0;

		subscription = events.register(TrailStepCompletedEvent.class, this::onStepCompleted);

		log.debug("Starting {} trail", trail.getMetadata().getTrailName());
		activateCurrentStep();
	}

	private void activateCurrentStep()
	{
		if (currentIndex >= trail.getSteps().size())
		{
			log.debug("Trail completed");
			events.publish(new TrailCompletedEvent(trail, context));
			return;
		}

		TrailStep step = getCurrentStep();

		activeHandler = stepHandlerFactory.createHandler(step, context);
		log.debug("Activated step {}", currentIndex);
	}

	public TrailStep getCurrentStep()
	{
		if (trail == null)
		{
			return null;
		}
		if (trail.getSteps().size() <= currentIndex)
		{
			return null;
		}

		return trail.getSteps().get(currentIndex);
	}

	private void onStepCompleted(TrailStepCompletedEvent event)
	{
		log.debug("Step {} completed", currentIndex);

		deactivateCurrentHandler();

		currentIndex++;
		activateCurrentStep();
	}

	private void deactivateCurrentHandler()
	{
		if (activeHandler != null)
		{
			activeHandler.onDeactivate(); // recommend adding this
			activeHandler = null;
		}
	}

	public void reset()
	{
		deactivateCurrentHandler();

		trail = null;
		context = null;
		currentIndex = 0;

		if (subscription != null) {
			subscription.unsubscribe();
			subscription = null;
		}
	}
}

package dev.hollink.partytrails.engine.hunter.handlers;

import dev.hollink.partytrails.data.steps.SkillStep;
import dev.hollink.partytrails.data.trail.TrailContext;
import dev.hollink.partytrails.events.Subscription;
import dev.hollink.partytrails.events.TrailEventBus;
import dev.hollink.partytrails.events.events.SkillEvent;
import dev.hollink.partytrails.events.events.TrailStepCompletedEvent;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class SkillStepHandler implements StepHandler<SkillEvent>
{
	private final TrailEventBus events;
	private final SkillStep step;
	private final TrailContext context;
	private final Subscription subscription;

	public SkillStepHandler(TrailEventBus events, SkillStep step, TrailContext context)
	{
		this.events = events;
		this.step = step;
		this.context = context;

		storeStartingExperience();

		this.subscription = events.register(SkillEvent.class, this::onEvent);
	}

	public void storeStartingExperience()
	{
		String key = getContextKey(context);

		log.debug("Set initial experience for {} in the skill-step state", step.getSkill().getName());
		int startExp = context.getSkillExperience(step.getSkill());
		context.getProgress().storeInt(key, startExp);
	}

	@Override
	public void onDeactivate()
	{
		subscription.unsubscribe();

		log.debug("Clearing skill step state from context.");
		context.getProgress().getStepState().clear();
	}

	@Override
	public void onEvent(SkillEvent event)
	{
		if (step.getSkill() != event.getSkill())
		{
			return;
		}

		if (!context.getClient().getLocalPlayer().getWorldLocation().isInArea(step.getArea()))
		{
			log.debug("Player performed skilling action for {} outside of target area!", step.getSkill().getName());
			return;
		}

		String key = getContextKey(context);
		int startExp = context.getProgress().getStoredInt(key);
		int expDiff = event.getXp() - startExp;

		if (expDiff < step.getExpRequired())
		{
			log.debug("Player performed skilling action for {}", step.getSkill().getName());
			return;
		}

		events.publish(new TrailStepCompletedEvent(step, context));
	}

	private String getContextKey(TrailContext context)
	{
		int stepIndex = context.getProgress().getCurrentStepIndex();
		String skillName = step.getSkill().getName().toLowerCase();
		return String.format("step.%d.%s-experience", stepIndex, skillName);
	}
}

package dev.hollink.partytrails.engine.hunter.handlers;

import dev.hollink.partytrails.data.steps.InteractionStep;
import dev.hollink.partytrails.data.trail.TrailContext;
import dev.hollink.partytrails.events.Subscription;
import dev.hollink.partytrails.events.TrailEventBus;
import dev.hollink.partytrails.events.events.InteractionEvent;
import dev.hollink.partytrails.events.events.TrailStepCompletedEvent;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class InteractionStepHandler implements StepHandler<InteractionEvent>
{
	private final TrailEventBus events;
	private final InteractionStep step;
	private final TrailContext context;
	private final Subscription subscription;

	public InteractionStepHandler(TrailEventBus events, InteractionStep step, TrailContext context)
	{
		this.events = events;
		this.step = step;
		this.context = context;

		this.subscription = events.register(InteractionEvent.class, this::onEvent);
	}

	@Override
	public void onEvent(InteractionEvent event)
	{
		boolean isMet = event.getObjectId() == step.getTarget().getTargetId()
			&& event.getObjectName().equalsIgnoreCase(step.getTarget().getTargetName())
			&& event.getAction().equalsIgnoreCase(step.getTarget().getInteractionType())
			&& event.getLocation().distanceTo(step.getTarget().getLocation()) <= 2;

		if (isMet)
		{
			log.debug("Player interacted with target: {}", step.getTarget().getTargetName());
			events.publish(new TrailStepCompletedEvent(step, context));
		}
	}

	@Override
	public void onDeactivate()
	{
		subscription.unsubscribe();
	}
}

package dev.hollink.partytrails.engine.hunter.handlers;

import dev.hollink.partytrails.data.steps.CoordsStep;
import dev.hollink.partytrails.data.steps.EmoteStep;
import dev.hollink.partytrails.data.steps.InteractionStep;
import dev.hollink.partytrails.data.steps.SkillStep;
import dev.hollink.partytrails.data.steps.TrailStep;
import dev.hollink.partytrails.data.trail.TrailContext;
import dev.hollink.partytrails.events.TrailEventBus;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class StepHandlerFactory
{
	private final TrailEventBus events;

	public StepHandler<?> createHandler(TrailStep step, TrailContext context)
	{
		switch (step.getStepType())
		{
			case EMOTE_STEP:
				return new EmoteStepHandler(events, (EmoteStep) step, context);
			case COORDINATE_STEP:
				return new CoordinateStepHandler(events, (CoordsStep) step, context);
			case SKILL_STEP:
				return new SkillStepHandler(events, (SkillStep) step, context);
			case CIPHER_STEP:
			case ANAGRAM_STEP:
			case CRYPTIC_STEP:
				return new InteractionStepHandler(events, (InteractionStep) step, context);

			default:
				throw new IllegalArgumentException("Unknown step type: " + step.getStepType());
		}
	}
}

