@Slf4j
@Singleton
public final class TrailBuilderPanel extends PluginPanel implements FormHelper
{
	private final Client client;
	private final ConfigManager config;
	private final TrailEventBus clueEventBus;
	private final TrailCodec codec;

	private final JTextField nameField = new JTextField();

	private final JPanel stepsContainer = new JPanel();

	@Getter
	private final List<StepEditorPanel> editors = new ArrayList<>();

	public TrailBuilderPanel(Client client, ConfigManager config, TrailEventBus clueEventBus, TrailCodec codec)
	{
		this.client = client;
		this.config = config;
		this.clueEventBus = clueEventBus;
		this.codec = codec;
	}

	public void enableTrailBuilder()
	{
		removeAll();

		JScrollPane form = createForm();
		add(form, BorderLayout.CENTER);
	}

	public void disableTrailBuilder()
	{
		removeAll();

		PluginErrorPanel pluginErrorPanel = new PluginErrorPanel();
		pluginErrorPanel.setContent("Party Trails", "Sign in to start the builder.");
		add(pluginErrorPanel);
	}

	private void addMetadataSection(JPanel form)
	{
		nameField.setMaximumSize(new Dimension(230, nameField.getPreferredSize().height));
		form.add(createRow("Trail name", nameField));
	}

	private void addStepsSection(JPanel form)
	{
		JButton addStep = new JButton("Add Step");
		addStep.addActionListener(e -> addStep());
		addStep.setMaximumSize(new Dimension(230, addStep.getPreferredSize().height));

		stepsContainer.setLayout(new BoxLayout(stepsContainer, BoxLayout.Y_AXIS));
		form.add(stepsContainer);
		form.add(addStep);
	}

	private void addStep()
	{
		StepEditorPanel panel = new StepEditorPanel(this.clueEventBus, this::removeStep, this::updateUI);
		editors.add(panel);
		rebuildSteps();
	}

	private void removeStep(StepEditorPanel panel)
	{
		editors.remove(panel);
		rebuildSteps();
	}

	private void rebuildSteps()
	{
		stepsContainer.removeAll();

		for (int i = 0; i < editors.size(); i++)
		{
			StepEditorPanel editor = editors.get(i);
			editor.setStepNumber(i + 1);
			stepsContainer.add(editor);
			stepsContainer.add(Box.createVerticalStrut(8));
		}

		stepsContainer.revalidate();
		stepsContainer.repaint();
		updateUI();
	}

	private void addButtons(JPanel root)
	{
		JButton encode = new JButton("Copy Trial to clipboard");
		encode.setMaximumSize(new Dimension(230, encode.getPreferredSize().height));
		encode.addActionListener(e -> encodeTrail(this::copyTrailToClipboard));

		JButton save = getLoadSaveButton("Save to plugin config", e -> encodeTrail(this::saveTrailToConfig));
		JButton load = getLoadSaveButton("Load from plugin config", e -> reloadSave());

		root.add(Box.createVerticalStrut(8));
		root.add(encode);

		root.add(Box.createVerticalStrut(32));
		root.add(save);
		root.add(Box.createVerticalStrut(8));
		root.add(load);
	}

	private JButton getLoadSaveButton(String text, ActionListener actionListener)
	{
		JButton button = new JButton(text);
		button.setMaximumSize(new Dimension(230, button.getPreferredSize().height));
		button.addActionListener(actionListener);
		FlatButtonBorder border = new FlatButtonBorder();
		border.applyStyleProperty("borderColor", new Color(0, 0, 0, 0.05f));
		button.setBackground(new Color(0, 0, 0, 0.05f));
		button.setBorder(border);
		return button;
	}

	private void encodeTrail(Consumer<String> callback)
	{
		if (showValidationErrors())
		{
			return;
		}

		try
		{
			TreasureTrail trail = generateTrailFromBuilderInput();
			String encodeTrail = codec.encodeToString(trail);
			callback.accept(encodeTrail);
		}
		catch (IOException e)
		{
			throw new RuntimeException(e);
		}
	}

	private void copyTrailToClipboard(String encodeTrail)
	{
		Toolkit.getDefaultToolkit()
			.getSystemClipboard()
			.setContents(new StringSelection(encodeTrail), null);
		JOptionPane.showMessageDialog(this, "Trail copied to clipboard!");
	}

	private void saveTrailToConfig(String encodeTrail)
	{
		config.setConfiguration(PartyTrailsConfig.CONFIG_GROUP, PartyTrailsConfig.BUILDER_STATE, encodeTrail);
		JOptionPane.showMessageDialog(this, "Trail saved!");
	}

	private TreasureTrail generateTrailFromBuilderInput()
	{
		List<TrailStep> steps = editors.stream()
			.map(StepEditorPanel::toTrailStep)
			.collect(Collectors.toList());

		return new TreasureTrail(
			1,
			RandomUtil.randomAlphanumeric(16),
			nameField.getText(),
			client.getLocalPlayer().getName(),
			steps
		);
	}

	private boolean showValidationErrors()
	{
		if (client.getLocalPlayer() == null)
		{
			JOptionPane.showMessageDialog(this, "You must be logged in to encode a trail", "Error", JOptionPane.ERROR_MESSAGE);
			return true;
		}

		if (nameField.getText().isBlank())
		{
			JOptionPane.showMessageDialog(this, "Trail name required", "Error", JOptionPane.ERROR_MESSAGE);
			return true;
		}

		if (editors.isEmpty())
		{
			JOptionPane.showMessageDialog(this, "Add at least one step", "Error", JOptionPane.ERROR_MESSAGE);
			return true;
		}

		String errors = getStepErrors();
		if (!errors.isBlank())
		{
			JOptionPane.showMessageDialog(this, errors, "Error", JOptionPane.ERROR_MESSAGE);
			return true;
		}

		return false;
	}

	private String getStepErrors()
	{
		return editors.stream()
			.flatMap(editor -> editor.getValidationErrors().stream())
			.sorted(Comparator.comparingInt(StepEditorValidationError::getStepIndex))
			.map(error -> String.format("Step %d: %s", error.getStepIndex(), error.getErrorMessage()))
			.collect(Collectors.joining("\n"));
	}

	private void reloadSave()
	{
		TreasureTrail treasureTrail = getSavedTrailFromConfig();
		if (treasureTrail == null)
		{
			return;
		}

		nameField.setText(treasureTrail.getMetadata().getTrailName());
		editors.clear();
		for (int i = 0; i < treasureTrail.getSteps().size(); i++)
		{
			StepEditorPanel step = new StepEditorPanel(clueEventBus, this::removeStep, this::updateUI);
			step.reloadTrailStep(i, treasureTrail.getSteps().get(i));
			editors.add(step);
		}
		rebuildSteps();
		JOptionPane.showMessageDialog(this, "Successfully loaded save for:\n" + treasureTrail.getMetadata().getTrailName());
	}

	private TreasureTrail getSavedTrailFromConfig()
	{
		String configuredSave = config.getConfiguration(PartyTrailsConfig.CONFIG_GROUP, PartyTrailsConfig.BUILDER_STATE);
		if (configuredSave == null || configuredSave.isBlank())
		{
			JOptionPane.showMessageDialog(this, "No save found in plugin configuration",
				"Error", JOptionPane.ERROR_MESSAGE);
			return null;
		}

		TreasureTrail treasureTrail = null;
		try
		{
			treasureTrail = codec.decode(configuredSave);
		}
		catch (Exception e)
		{
			JOptionPane.showMessageDialog(this, "Problem encountered while decoding progress: " + e.getMessage(),
				"Error", JOptionPane.ERROR_MESSAGE);
			return null;
		}

		String playerName = client.getLocalPlayer().getName();
		String trailAuthor = treasureTrail.getMetadata().getAuthor();
		if (!trailAuthor.equals(playerName))
		{
			JOptionPane.showMessageDialog(this, "You can only reload trails that belong to your account!",
				"Warning", JOptionPane.ERROR_MESSAGE);
			return null;
		}
		return treasureTrail;
	}

	private JScrollPane createForm()
	{
		JPanel form = new JPanel();
		form.setLayout(new BoxLayout(form, BoxLayout.Y_AXIS));

		addMetadataSection(form);
		addStepsSection(form);
		addButtons(form);

		// Start with a single step already present!
		addStep();

		JScrollPane scrollPane = new JScrollPane(form);
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);

		return scrollPane;
	}
}

package dev.hollink.partytrails.engine.builder;

import dev.hollink.partytrails.PartyTrailsConfig;
import dev.hollink.partytrails.data.steps.CoordsStep;
import dev.hollink.partytrails.data.steps.EmoteStep;
import dev.hollink.partytrails.data.steps.InteractionStep;
import dev.hollink.partytrails.data.steps.SkillStep;
import dev.hollink.partytrails.data.steps.TrailStep;
import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Slf4j
@Singleton
public final class TrailBuilderOverlay extends Overlay
{

	private final Client client;
	private final PartyTrailsConfig config;
	private final TrailBuilderPanel builderPanel;

	@Inject
	public TrailBuilderOverlay(Client client, PartyTrailsConfig config, TrailBuilderPanel builderPanel)
	{
		this.client = client;
		this.config = config;
		this.builderPanel = builderPanel;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics2D)
	{
		if (!config.showBuilderOverlay())
		{
			return null;
		}


		List<StepEditorPanel> steps = List.copyOf(builderPanel.getEditors());
		for (int i = 0; i < steps.size(); i++)
		{
			renderStepOverlay(steps.get(i).toTrailStep(), graphics2D, i);
		}

		return null;
	}

	private void renderStepOverlay(TrailStep configuredStep, Graphics2D graphics2D, int stepNumber)
	{
		if (configuredStep instanceof EmoteStep)
		{
			renderStepOverlay((EmoteStep) configuredStep, stepNumber, graphics2D);
		}
		else if (configuredStep instanceof InteractionStep)
		{
			renderStepOverlay((InteractionStep) configuredStep, stepNumber, graphics2D);

		}
		else if (configuredStep instanceof CoordsStep)
		{
			renderStepOverlay((CoordsStep) configuredStep, stepNumber, graphics2D);
		}
		else if (configuredStep instanceof SkillStep)
		{
			renderStepOverlay((SkillStep) configuredStep, stepNumber, graphics2D);

		}

	}

	private void renderStepOverlay(InteractionStep step, int stepNumber, Graphics2D graphics2D)
	{
		if (step.getTarget() == null || step.getTarget().getLocation() == null)
		{
			return;
		}
		if (step.getTarget().getLocation().getPlane() != client.getLocalPlayer().getWorldLocation().getPlane())
		{
			return;
		}

		renderTile(graphics2D, step.getTarget().getLocation(), String.format("Step %s", stepNumber));
	}

	private void renderStepOverlay(SkillStep step, int stepNumber, Graphics2D graphics2D)
	{
		if (step.getArea() == null)
		{
			return;
		}
		if (step.getArea().getPlane() != client.getLocalPlayer().getWorldLocation().getPlane())
		{
			return;
		}

		renderWorldAreaOutline(graphics2D, step.getArea(), String.format("Step %s", stepNumber));
	}

	private void renderStepOverlay(CoordsStep step, int stepNumber, Graphics2D graphics2D)
	{
		if (step.getTargetLocation() == null)
		{
			return;
		}
		if (step.getTargetLocation().getPlane() != client.getLocalPlayer().getWorldLocation().getPlane())
		{
			return;
		}

		renderTile(graphics2D, step.getTargetLocation(), String.format("Step %s", stepNumber));
	}

	private void renderStepOverlay(EmoteStep step, int stepNumber, Graphics2D graphics2D)
	{
		if (step.getTargetLocation() == null)
		{
			return;
		}
		if (step.getTargetLocation().getPlane() != client.getLocalPlayer().getWorldLocation().getPlane())
		{
			return;
		}

		renderTile(graphics2D, step.getTargetLocation(), String.format("Step %s", stepNumber));
	}


	private void renderTile(Graphics2D graphics, WorldPoint worldPoint, String text)
	{
		LocalPoint localPoint = LocalPoint.fromWorld(client, worldPoint);
		if (localPoint == null)
		{
			return;
		}

		Polygon poly = Perspective.getCanvasTilePoly(client, localPoint);
		if (poly == null)
		{
			return;
		}

		graphics.setColor(config.builderOverlayColor());
		graphics.drawPolygon(poly);

		drawText(graphics, text, localPoint);
	}

	private void renderWorldAreaOutline(Graphics2D graphics, WorldArea area, String text)
	{
		int x1 = area.getX();
		int y1 = area.getY();
		int x2 = x1 + area.getWidth();
		int y2 = y1 + area.getHeight();
		int plane = area.getPlane();

		WorldPoint sw = new WorldPoint(x1, y1, plane);
		WorldPoint nw = new WorldPoint(x1, y2, plane);
		WorldPoint ne = new WorldPoint(x2, y2, plane);
		WorldPoint se = new WorldPoint(x2, y1, plane);

		LocalPoint lsw = LocalPoint.fromWorld(client, sw);
		LocalPoint lnw = LocalPoint.fromWorld(client, nw);
		LocalPoint lne = LocalPoint.fromWorld(client, ne);
		LocalPoint lse = LocalPoint.fromWorld(client, se);

		if (lsw == null || lnw == null || lne == null || lse == null)
		{
			return;
		}

		Polygon poly = new Polygon();

		addPoint(poly, lsw);
		addPoint(poly, lnw);
		addPoint(poly, lne);
		addPoint(poly, lse);

		graphics.setColor(config.builderOverlayColor());
		graphics.setStroke(new BasicStroke(2));
		graphics.drawPolygon(poly);
		drawText(graphics, text, lsw);
	}

	private void addPoint(Polygon poly, LocalPoint lp)
	{
		Point p = Perspective.localToCanvas(client, lp, client.getWorldView(lp.getWorldView()).getPlane());
		if (p != null)
		{
			poly.addPoint(p.getX(), p.getY());
		}
	}

	private void drawText(Graphics2D graphics, String text, LocalPoint localPoint)
	{
		Point canvasTextLocation = Perspective.getCanvasTextLocation(client, graphics, localPoint, text, 0);
		if (canvasTextLocation != null)
		{
			graphics.setColor(config.builderOverlayColor());
			graphics.drawString(text, canvasTextLocation.getX(), canvasTextLocation.getY());
		}
	}
}

package dev.hollink.partytrails.engine.builder.fields;

import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import javax.swing.Box;
import javax.swing.JPanel;
import javax.swing.JTextField;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;

public final class RegionSelector extends LocationSelector
{
	private final JTextField widthField = new JTextField();
	private final JTextField heightField = new JTextField();

	public RegionSelector()
	{
		super();
		JPanel whPanel = new JPanel();
		whPanel.setLayout(new FlowLayout(FlowLayout.CENTER));
		whPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		whPanel.add(createRow("Width", widthField));
		whPanel.add(Box.createVerticalStrut(5));
		whPanel.add(createRow("Height", heightField));

		setupFields();

		add(whPanel);
	}

	private void setupFields()
	{
		widthField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		heightField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
	}

	public WorldArea getWorldArea()
	{
		try
		{
			int x = Integer.parseInt(xField.getText());
			int y = Integer.parseInt(yField.getText());
			int w = Integer.parseInt(widthField.getText());
			int h = Integer.parseInt(heightField.getText());
			int plane = Integer.parseInt(planeField.getText());

			return new WorldArea(x, y, w, h, plane);
		}
		catch (Exception e)
		{
			return null;
		}
	}

	public boolean setSize(WorldPoint point)
	{
		WorldPoint initialLocation = getWorldLocation();
		if (initialLocation == null)
		{
			setLocation(point);
			return false;
		}
		if (initialLocation.getPlane() != point.getPlane())
		{
			return false;
		}
		int xDiff = initialLocation.getX() - point.getX();
		int yDiff = initialLocation.getY() - point.getY();

		if (xDiff == 0 || yDiff == 0)
		{
			return false;
		}

		widthField.setText(String.valueOf(Math.abs(xDiff)));
		heightField.setText(String.valueOf(Math.abs(yDiff)));

		if (xDiff > 0)
		{
			xField.setText(String.valueOf(point.getX()));
		}
		if (yDiff > 0)
		{
			yField.setText(String.valueOf(point.getY()));
		}

		return true;
	}

	public void setWorldArea(WorldArea area)
	{
		xField.setText(String.valueOf(area.getX()));
		yField.setText(String.valueOf(area.getY()));
		planeField.setText(String.valueOf(area.getPlane()));
		widthField.setText(String.valueOf(area.getWidth()));
		heightField.setText(String.valueOf(area.getHeight()));
	}
}

